/**
 * @ohhi/i18n — the dictionaries and the typesafe-i18n wiring, laid out as
 * Edible's `@edible/shared/i18n` is:
 *
 *   src/i18n/en/index.ts        the root dictionary (`common`)
 *   src/i18n/en/web/index.ts    the `web` namespace — the shell's copy
 *   src/i18n/i18n-*.ts          GENERATED by `rushx generate`; never edited
 *   src/i18n/formatters.ts      per-locale formatters (hand-written)
 *
 * Components subscribe to the store: `import { LL } from '@ohhi/i18n/i18n-svelte'`
 * then `const t = $derived($LL.web.tree)`. Modules that are not components
 * (`.ts`, `.svelte.ts`) call `getLL()` below — the same `TranslationFunctions`
 * object, read from the store at call time, so the pure modules stay
 * unit-testable on node once a test setup has called `loadLocale` + `setLocale`.
 */
import { get } from 'svelte/store'
import { LL } from './i18n/i18n-svelte.js'
import type { TranslationFunctions } from './i18n/i18n-types.js'

export * from './i18n/i18n-types.js'
export * from './i18n/lang-labels.js'

/** The active locale's translation functions, for code that cannot `$LL`. */
export const getLL = (): TranslationFunctions => get(LL)
